    37  static void vcardstructured_free(vcardstructuredtype *st)
    38  {
    39      for (size_t i = 0; i < st->num_fields; i++) {
    40          if (st->field[i]) {
    41              vcardstrarray_free(st->field[i]);
    42          }
    43      }
    44      icalmemory_free_buffer((void *)st);
    45  }
    46
    47  vcardstructuredtype *vcardstructured_new(size_t num_fields)
    48  {
    49      struct vcardstructuredtype_impl *st = vcardstructured_alloc();
    50      if (!st) {
    51          return st;
    52      }
    53      vcardstructured_ref(st);
    54
    55      st->num_fields = num_fields;
    56      return st;
    57  }
