    47  void vcardparameter_free(vcardparameter *param)
    48  {
    49      if (!param || param->parent != 0) {
    50          return;
    51      }
    52
    53      if (param->string != 0) {
    54          icalmemory_free_buffer((void *)param->string);
    55      } else if (param->values != 0) {
    56          if (param->value_kind == VCARD_TEXT_VALUE) {
    57              vcardstrarray_free(param->values);
    58          } else {
    59              vcardenumarray_free(param->values);
    60          }
    61      } else if (param->structured != 0) {
    62          vcardstructured_unref(param->structured);
    63      }
    64
    65      if (param->x_name != 0) {
    66          icalmemory_free_buffer((void *)param->x_name);
    67      }
    68
    69      memset(param, 0, sizeof(vcardparameter));
    70
    71      param->parent = 0;
    72      param->id[0] = 'X';
    73      icalmemory_free_buffer(param);
    74  }
