    76  vcardparameter *vcardparameter_clone(const vcardparameter *old)
    77  {
    78      struct vcardparameter_impl *clone;
    79
    80      icalerror_check_arg_rz((old != 0), "param");
    81
    82      clone = vcardparameter_new_impl(old->kind);
    83
    84      if (clone == 0) {
    85          return 0;
    86      }
    87
    88      memcpy(clone, old, sizeof(struct vcardparameter_impl));
    89
    90      if (old->string != 0) {
    91          clone->string = icalmemory_strdup(old->string);
    92          if (clone->string == 0) {
    93              clone->parent = 0;
    94              vcardparameter_free(clone);
    95              return 0;
    96          }
    97      }
    98
    99      if (old->x_name != 0) {
   100          clone->x_name = icalmemory_strdup(old->x_name);
   101          if (clone->x_name == 0) {
   102              clone->parent = 0;
   103              vcardparameter_free(clone);
   104              return 0;
   105          }
   106      }
   107
   108      if (old->values != 0) {
   109          clone->values = old->value_kind == VCARD_TEXT_VALUE ? vcardstrarray_clone(old->values) : vcardenumarray_clone(old->values);
   110          if (clone->values == 0) {
   111              clone->parent = 0;
   112              vcardparameter_free(clone);
   113              return 0;
   114          }
   115      }
   116
   117      return clone;
