   120  vcardparameter *vcardparameter_new_from_string(const char *str)
   121  {
   122      char *eq;
   123      char *cpy;
   124      vcardparameter_kind kind;
   125      vcardparameter *param;
   126
   127      icalerror_check_arg_rz(str != 0, "str");
   128
   129      cpy = icalmemory_strdup(str);
   130
   131      if (cpy == 0) {
   132          icalerror_set_errno(ICAL_NEWFAILED_ERROR);
   133          return 0;
   134      }
   135
   136      eq = strchr(cpy, '=');
   137
   138      if (eq == 0) {
   139          icalerror_set_errno(ICAL_MALFORMEDDATA_ERROR);
   140          icalmemory_free_buffer(cpy);
   141          return 0;
   142      }
   143
   144      *eq = '\0';
   145
   146      eq++;
   147
   148      kind = vcardparameter_string_to_kind(cpy);
   149
   150      if (kind == VCARD_NO_PARAMETER) {
   151          icalerror_set_errno(ICAL_MALFORMEDDATA_ERROR);
   152          icalmemory_free_buffer(cpy);
   153          return 0;
   154      }
   155
   156      param = vcardparameter_new_from_value_string(kind, eq);
   157
   158      if (kind == VCARD_X_PARAMETER) {
   159          vcardparameter_set_xname(param, cpy);
   160      } else if (kind == VCARD_IANA_PARAMETER) {
   161          vcardparameter_set_iana_name(param, cpy);
   162      }
   163
   164      icalmemory_free_buffer(cpy);
   165
   166      return param;
