   169  char *vcardparameter_as_vcard_string(vcardparameter *param)
   170  {
   171      char *buf;
   172
   173      buf = vcardparameter_as_vcard_string_r(param);
   174      icalmemory_add_tmp_buffer(buf);
   175      return buf;
   176  }
   177
   178  /*
   179   * - param        = param-name "=" param-value
   180   * - param-name   = iana-token / x-token
   181   * - param-value  = paramtext /quoted-string
   182   * - paramtext    = *SAFE-CHAR
   183   * - quoted-string= DQUOTE *QSAFE-CHAR DQUOTE
   184   * - QSAFE-CHAR   = any character except CTLs and DQUOTE
   185   * - SAFE-CHAR    = any character except CTLs, DQUOTE. ";", ":", ","
   186   */
   187  char *vcardparameter_as_vcard_string_r(vcardparameter *param)
   188  {
   189      size_t buf_size = 1024;
   190      char *buf;
   191      char *buf_ptr;
   192
   193      icalerror_check_arg_rz((param != 0), "parameter");
   194
   195      /* Create new buffer that we can append names, parameters and a
   196       * value to, and reallocate as needed.
   197       */
   198
   199      buf = icalmemory_new_buffer(buf_size);
   200      buf_ptr = buf;
   201
   202      if (param->kind == VCARD_X_PARAMETER) {
   203          icalmemory_append_string(&buf, &buf_ptr,
   204                                   &buf_size, vcardparameter_get_xname(param));
   205      } else if (param->kind == VCARD_IANA_PARAMETER) {
   206          icalmemory_append_string(&buf, &buf_ptr,
   207                                   &buf_size, vcardparameter_get_iana_name(param));
   208      } else {
   209          const char *kind_string = vcardparameter_kind_to_string(param->kind);
   210
   211          if (param->kind == VCARD_NO_PARAMETER ||
   212              param->kind == VCARD_ANY_PARAMETER || kind_string == 0) {
   213              icalerror_set_errno(ICAL_BADARG_ERROR);
   214              icalmemory_free_buffer(buf);
   215              return 0;
   216          }
   217
   218          /* Put the parameter name into the string */
   219          icalmemory_append_string(&buf, &buf_ptr, &buf_size, kind_string);
   220      }
   221
   222      icalmemory_append_string(&buf, &buf_ptr, &buf_size, "=");
   223
   224      if (param->string != 0) {
   225          icalmemory_append_encoded_string(&buf, &buf_ptr,
   226                                           &buf_size, param->string);
   227      } else if (param->data != 0) {
   228          char *intbuf = NULL;
   229          const char *str;
   230
   231          if (param->value_kind == VCARD_INTEGER_VALUE) {
   232  #define VCARD_INTEGER_LENGTH 21
   233              intbuf = icalmemory_tmp_buffer(VCARD_INTEGER_LENGTH);
   234              snprintf(intbuf, VCARD_INTEGER_LENGTH - 1, "%d", param->data);
   235
   236              str = intbuf;
   237          } else {
   238              str = vcardparameter_enum_to_string(param->data);
   239          }
   240
   241          icalmemory_append_string(&buf, &buf_ptr, &buf_size, str);
   242
   243      } else if (param->values != 0) {
   244          size_t i;
   245          const char *sep = "";
   246
   247          for (i = 0; i < param->values->num_elements; i++) {
   248              icalmemory_append_string(&buf, &buf_ptr, &buf_size, sep);
   249
   250              if (param->value_kind == VCARD_TEXT_VALUE) {
   251                  const char *str = vcardstrarray_element_at(param->values, i);
   252
   253                  icalmemory_append_encoded_string(&buf, &buf_ptr,
   254                                                   &buf_size, str);
   255              } else {
   256                  const vcardenumarray_element *elem =
   257                      vcardenumarray_element_at(param->values, i);
   258                  if (elem->xvalue != 0) {
   259                      icalmemory_append_encoded_string(&buf, &buf_ptr,
   260                                                       &buf_size, elem->xvalue);
   261                  } else {
   262                      const char *str = vcardparameter_enum_to_string(elem->val);
   263
   264                      icalmemory_append_string(&buf, &buf_ptr, &buf_size, str);
   265                  }
   266              }
   267              sep = ",";
   268          }
   269      } else if (vcardparameter_is_structured(param)) {
   270          char *str = vcardstructured_as_vcard_string_r(param->structured, 1);
   271
   272          icalmemory_append_encoded_string(&buf, &buf_ptr, &buf_size, str);
   273          icalmemory_free_buffer(str);
   274      } else if (vcardtime_is_valid_time(param->date)) {
   275          const char *str = vcardtime_as_vcard_string(param->date, 0);
   276
   277          icalmemory_append_string(&buf, &buf_ptr, &buf_size, str);
   278
   279      } else {
   280          icalerror_set_errno(ICAL_MALFORMEDDATA_ERROR);
   281          icalmemory_free_buffer(buf);
   282          return 0;
   283      }
   284
   285      return buf;
   286  }
